var a=[{title:`Varför det spelar roll`,text:`Med åldern förändras ofta muskelmassa, styrka, explosivitet och balans, även om takten varierar mycket mellan människor. Styrketräning kan göra vardagliga uppgifter lättare, som att resa sig från en stol, gå i trappor och bära matkassar. Aerob aktivitet stöder hjärt-kärlhälsa och uthållighet.`},{title:`Träna flera förmågor`,text:`En praktisk vecka blandar styrketräning, måttlig aerob aktivitet och viss balansträning. Officiella riktlinjer för vuxna från 65 år rekommenderar specifikt minst 150 minuters måttlig aerob aktivitet i veckan, muskelstärkande träning två dagar och balansövningar. Som femtioåring, följ de allmänna aktivitetsriktlinjerna för vuxna.`},{title:`Välj användbara rörelser`,text:`Uppresningar från sittande, stödda uppsteg, rodd, pressar och bärande kan alla anpassas till där du befinner dig nu. Vissa friska äldre vuxna har nytta av övervakade kraftövningar som görs med kontroll och snabb intention. Det betyder inte att man ska hoppa in i riskabel träning med stora stötar utan förberedelse.`},{title:`Gå vidare med återkoppling`,text:`Gör övningar svårare när din färdighet och styrka förbättras, men räkna med att återhämtningen beror på hälsotillstånd, sömn och tidigare träning. Sök professionell rådgivning vid ny yrsel, bröstsymtom, oförklarlig smärta eller balansproblem. Din ålder är ingen diagnos och kan inte ersätta en ordentlig bedömning, och ensam är den inget skäl att utesluta tyngre träning.`}];var e=[{label:`CDC: fysisk aktivitet för äldre vuxna`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/older-adults.html`},{label:`ACSM:s ställningstagande 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var n={sections:a,sources:e};export{n as default,a as sections,e as sources};